using Segment = tuple<int, int, int, int>;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    set<Segment> segments;
    int minX = INT_MAX, maxX = INT_MIN;
    int minY = INT_MAX, maxY = INT_MIN;

    for (int i = 0; i < 4; ++i) {
        int x1, y1, x2, y2;
        if (!(cin >> x1 >> y1 >> x2 >> y2)) return 0;

        if ((x1 == x2 && y1 == y2) || (x1 != x2 && y1 != y2)) {
            cout << "NO\n";
            return 0;
        }

        if (make_pair(x2, y2) < make_pair(x1, y1)) {
            swap(x1, x2);
            swap(y1, y2);
        }

        segments.emplace(x1, y1, x2, y2);
        minX = min({minX, x1, x2});
        maxX = max({maxX, x1, x2});
        minY = min({minY, y1, y2});
        maxY = max({maxY, y1, y2});
    }

    if (minX == maxX || minY == maxY || segments.size() != 4) {
        cout << "NO\n";
        return 0;
    }

    set<Segment> expected = {
        {minX, minY, maxX, minY},
        {minX, maxY, maxX, maxY},
        {minX, minY, minX, maxY},
        {maxX, minY, maxX, maxY}
    };

    cout << (segments == expected ? "YES\n" : "NO\n");
    return 0;
}

#include <iostream>
#include <vector>
