#include <cstdlib>
using namespace std;

struct Line {
    int x1, y1, x2, y2;
    bool vertical;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<Line> lines;
    int verticalCount = 0;
    int horizontalCount = 0;

    for (int i = 0; i < 4; ++i) {
        int x1, y1, x2, y2;
        if (!(cin >> x1 >> y1 >> x2 >> y2)) {
            return 0;
        }

        if ((x1 == x2 && y1 == y2) || (x1 != x2 && y1 != y2)) {
            cout << "NO";
            return 0;
        }

        bool vertical = (x1 == x2);
        if (vertical) {
            if (y1 > y2) swap(y1, y2);
            ++verticalCount;
        } else {
            if (x1 > x2) swap(x1, x2);
            ++horizontalCount;
        }

        lines.push_back({x1, y1, x2, y2, vertical});
    }

    if (verticalCount != 2 || horizontalCount != 2) {
        cout << "NO";
        return 0;
    }

    set<pair<pair<int, int>, pair<int, int>>> uniqueLines;
    map<pair<int, int>, pair<int, int>> incidence;

    for (const Line& line : lines) {
        pair<int, int> a = {line.x1, line.y1};
        pair<int, int> b = {line.x2, line.y2};

        if (!uniqueLines.insert({a, b}).second) {
            cout << "NO";
            return 0;
        }

        if (line.vertical) {
            ++incidence[a].first;
            ++incidence[b].first;
        } else {
            ++incidence[a].second;
            ++incidence[b].second;
        }
    }

    if (incidence.size() != 4) {
        cout << "NO";
        return 0;
    }

    for (const auto& entry : incidence) {
        if (entry.second.first != 1 || entry.second.second != 1) {
            cout << "NO";
            return 0;
        }
    }

    cout << "YES";
    return 0;
}

