using namespace std;

using Segment = tuple<int, int, int, int>;

Segment normalize(int x1, int y1, int x2, int y2) {
    if (make_pair(x2, y2) < make_pair(x1, y1)) {
        swap(x1, x2);
        swap(y1, y2);
    }
    return {x1, y1, x2, y2};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    set<Segment> segments;
    set<int> xs, ys;

    for (int i = 0; i < 4; ++i) {
        int x1, y1, x2, y2;
        if (!(cin >> x1 >> y1 >> x2 >> y2)) return 0;

        if ((x1 == x2 && y1 == y2) || (x1 != x2 && y1 != y2)) {
            cout << "NO";
            return 0;
        }

        segments.insert(normalize(x1, y1, x2, y2));
        xs.insert(x1);
        xs.insert(x2);
        ys.insert(y1);
        ys.insert(y2);
    }

    if (segments.size() != 4 || xs.size() != 2 || ys.size() != 2) {
        cout << "NO";
        return 0;
    }

    int left = *xs.begin();
    int right = *xs.rbegin();
    int bottom = *ys.begin();
    int top = *ys.rbegin();

    set<Segment> expected = {
        normalize(left, bottom, right, bottom),
        normalize(left, top, right, top),
        normalize(left, bottom, left, top),
        normalize(right, bottom, right, top)
    };

    cout << (segments == expected ? "YES" : "NO");
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>
using namespace std;

struct Line {
    int x1, y1, x2, y2;

    bool operator<(const Line& other) const {
        if (x1 != other.x1) return x1 < other.x1;
        if (y1 != other.y1) return y1 < other.y1;
        if (x2 != other.x2) return x2 < other.x2;
        return y2 < other.y2;
    }

    bool operator==(const Line& other) const {
        return x1 == other.x1 && y1 == other.y1 &&
               x2 == other.x2 && y2 == other.y2;
    }
};

Line normalize(int x1, int y1, int x2, int y2) {
    if (x1 > x2 || (x1 == x2 && y1 > y2)) {
        swap(x1, x2);
        swap(y1, y2);
    }
    return {x1, y1, x2, y2};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<Line> lines;
    int minX = INT_MAX, minY = INT_MAX;
    int maxX = INT_MIN, maxY = INT_MIN;

    for (int i = 0; i < 4; ++i) {
        int x1, y1, x2, y2;
        if (!(cin >> x1 >> y1 >> x2 >> y2)) {
            return 0;
        }

        if ((x1 != x2 && y1 != y2) || (x1 == x2 && y1 == y2)) {
            cout << "NO";
            return 0;
        }

        lines.push_back(normalize(x1, y1, x2, y2));
        minX = min(minX, min(x1, x2));
        maxX = max(maxX, max(x1, x2));
        minY = min(minY, min(y1, y2));
        maxY = max(maxY, max(y1, y2));
    }

    if (minX == maxX || minY == maxY) {
        cout << "NO";
        return 0;
    }

    vector<Line> expected = {
        normalize(minX, minY, maxX, minY),
        normalize(minX, maxY, maxX, maxY),
        normalize(minX, minY, minX, maxY),
        normalize(maxX, minY, maxX, maxY)
    };

    sort(lines.begin(), lines.end());
    sort(expected.begin(), expected.end());

    cout << (lines == expected ? "YES" : "NO");
    return 0;
}

